package com.yeyamo_mobile.api.recommendation_service.infrastructure.messaging;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.recommendation_service.application.RecommendationProjectionService;import com.yeyamo_mobile.api.recommendation_service.domain.*;
@Component public class RecommendationEventConsumer{private final ObjectMapper mapper;private final RecommendationProjectionService service;private final ProcessedEventRepository processed;public RecommendationEventConsumer(ObjectMapper m,RecommendationProjectionService s,ProcessedEventRepository p){mapper=m;service=s;processed=p;}@KafkaListener(topics="${yeyamo.kafka.topics.catalog-events:catalog.events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void catalog(String raw)throws Exception{handle(raw,"catalog");}@KafkaListener(topics="${yeyamo.kafka.topics.content-events:content.events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void content(String raw)throws Exception{handle(raw,"content");}@KafkaListener(topics="${yeyamo.kafka.topics.interaction-events:interaction.events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void interaction(String raw)throws Exception{handle(raw,"interaction");}@KafkaListener(topics="${yeyamo.kafka.topics.feed-events:feed.events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void feed(String raw)throws Exception{handle(raw,"feed");}@KafkaListener(topics="${yeyamo.kafka.topics.user-events:user.events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void user(String raw)throws Exception{handle(raw,"user");}
 private void handle(String raw,String source)throws Exception{JsonNode e=mapper.readTree(raw);UUID id=UUID.fromString(required(e,"eventId"));if(processed.existsById(id))return;if(e.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");String type=required(e,"eventType");JsonNode p=e.path("payload");switch(source){case"catalog"->catalog(type,p);case"content"->content(type,p);case"interaction"->interaction(type,p);case"feed"->feed(type,p);case"user"->user(type,p);default->throw new IllegalArgumentException("Unsupported source");}processed.save(new ProcessedEventEntity(id,type));}
 private void catalog(String type,JsonNode p){if(!type.startsWith("catalog.asset."))return;String id=required(p,"assetId"),source="catalog:"+id;CandidateKind kind=kind(text(p,"type","PLACE"));boolean active=!type.endsWith("deleted")&&"PUBLISHED".equals(text(p,"status","DRAFT"));service.candidate(new Candidate(source,id,kind,text(p,"name","Catalogue"),text(p,"categoryCode",null),text(p,"regionCode",null),text(p,"countryCode",null),text(p,"languageCode",null),number(p,"latitude"),number(p,"longitude"),0,active,active?Instant.now():null,Instant.now()));}
 private void content(String type,JsonNode p){if(!type.startsWith("content.post."))return;String id=required(p,"postId");boolean active=!type.endsWith("deleted")&&"PUBLISHED".equals(text(p,"status","DRAFT"))&&"PUBLIC".equals(text(p,"visibility","PRIVATE"));service.candidate(new Candidate("content:"+id,id,CandidateKind.CONTENT,text(p,"caption","Publication"),null,null,text(p,"countryCode",null),text(p,"languageCode",null),null,null,0,active,instant(p,"publishedAt"),Instant.now()));}
 private void interaction(String type,JsonNode p){String source;String user=text(p,"userId",text(p,"authorId",null));double delta=switch(type){case"interaction.like.added"->2;case"interaction.like.removed"->-2;case"interaction.favorite.added"->3;case"interaction.favorite.removed"->-3;case"interaction.comment.created"->1;case"interaction.comment.deleted"->-1;case"interaction.post.shared"->4;case"interaction.checkin.created"->5;default->0;};if(delta==0)return;if(type.equals("interaction.checkin.created"))source="catalog:"+required(p,"catalogAssetId");else source="content:"+required(p,"postId");service.popularity(source,delta);service.signal(user,source,delta);}
 private void feed(String type,JsonNode p){if("feed.metrics.updated".equals(type))service.popularity("content:"+required(p,"postId"),0.25);}
 private void user(String type,JsonNode p){if(!type.startsWith("profile.")&&!type.startsWith("User"))return;String user=required(p,"authUserId");if(type.equals("profile.location_updated")||type.equals("UserLocationUpdated")||type.equals("UserCountrySelected")){service.countryPreferences(user,text(p,"countryCode",null),null,null);return;}if(type.equals("profile.language_updated")||type.equals("UserLanguageUpdated")){service.countryPreferences(user,null,null,strings(p,"contentLanguages"));return;}if(type.equals("profile.discovery_preferences_updated")||type.equals("UserDiscoveryPreferencesUpdated")){service.countryPreferences(user,text(p,"countryCode",null),strings(p,"contentCountries"),null);return;}service.preference(user,text(p,"preferredRegionId",null),text(p,"language",text(p,"preferredLanguageCode",null)),p.path("locationSharingEnabled").asBoolean(false));}
 private CandidateKind kind(String value){try{return CandidateKind.valueOf(value.toUpperCase(Locale.ROOT));}catch(Exception e){return CandidateKind.PLACE;}}private String required(JsonNode n,String f){String v=text(n,f,null);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f,String fallback){JsonNode v=n.get(f);return v==null||v.isNull()||v.asText().isBlank()?fallback:v.asText();}private Double number(JsonNode n,String f){JsonNode v=n.get(f);return v==null||!v.isNumber()?null:v.asDouble();}private Instant instant(JsonNode n,String f){try{String v=text(n,f,null);return v==null?null:Instant.parse(v);}catch(Exception e){return null;}}private Set<String>strings(JsonNode n,String f){Set<String>values=new LinkedHashSet<>();JsonNode node=n.path(f);if(node.isArray())node.forEach(value->{if(!value.isNull()&&!value.asText().isBlank())values.add(value.asText());});return values;}
}
